import { comfortSkillIds, stepIndexById, surveySteps } from "./content.ts"
import type { SurveyOption, SurveyStep } from "./content.ts"
import type { ComfortSkill, CompanySize, OnboardingAnswers, ReferralSource, Role } from "./types.ts"
import { emptyAnswers } from "./types.ts"

/**
 * Pure survey state machine: no React, no DOM. The card components are a
 * thin render layer over these functions, which keeps validation and the
 * conditional follow-up step unit-testable in node.
 */

export interface SurveyState {
  readonly answers: OnboardingAnswers
  /** Index into the ACTIVE step list (see activeSteps). */
  readonly stepIndex: number
  /** Amber validation banner is showing for the current step. */
  readonly warned: boolean
  readonly submitted: boolean
}

export const initialSurveyState: SurveyState = {
  answers: emptyAnswers,
  stepIndex: 0,
  warned: false,
  submitted: false
}

/** The steps currently in play — the automation-goal text step only exists after a "Yes". */
export const activeSteps = (answers: OnboardingAnswers): ReadonlyArray<SurveyStep> =>
  surveySteps.filter((step) => step.id !== "automation-goal" || answers.knowsAutomationGoal === true)

export const currentStep = (state: SurveyState): SurveyStep => {
  const steps = activeSteps(state.answers)
  return steps[Math.min(state.stepIndex, steps.length - 1)]
}

export const progress = (state: SurveyState): { readonly current: number; readonly total: number } => {
  const steps = activeSteps(state.answers)
  return { current: Math.min(state.stepIndex, steps.length - 1), total: steps.length }
}

/** The selected option ids for a step, read out of the typed answers. */
export const selectionFor = (step: SurveyStep, answers: OnboardingAnswers): ReadonlyArray<string> => {
  switch (step.id) {
    case "company-size":
      return answers.companySize === null ? [] : [answers.companySize]
    case "role":
      return answers.role === null ? [] : [answers.role]
    case "referral":
      return answers.referralSource === null ? [] : [answers.referralSource]
    case "knows-goal":
      return answers.knowsAutomationGoal === null ? [] : [answers.knowsAutomationGoal ? "yes" : "not-yet"]
    case "automation-goal":
      return answers.automationGoal.trim() === "" ? [] : ["text"]
    case "comfort":
      return answers.comfortSkills
    default:
      return []
  }
}

const setSingle = (step: SurveyStep, answers: OnboardingAnswers, id: string): OnboardingAnswers => {
  switch (step.id) {
    case "company-size":
      return { ...answers, companySize: id as CompanySize }
    case "role":
      return { ...answers, role: id as Role }
    case "referral":
      return { ...answers, referralSource: id as ReferralSource }
    case "knows-goal": {
      const knows = id === "yes"
      // Flipping to "Not yet" also discards any typed goal so stale text
      // never ships with a contradictory answer.
      return { ...answers, knowsAutomationGoal: knows, automationGoal: knows ? answers.automationGoal : "" }
    }
    default:
      return answers
  }
}

const toggleMulti = (answers: OnboardingAnswers, option: SurveyOption): OnboardingAnswers => {
  const id = option.id as ComfortSkill
  if (!comfortSkillIds.includes(id)) return answers
  const current = answers.comfortSkills
  if (option.exclusive === true) {
    return { ...answers, comfortSkills: current.includes(id) && current.length === 1 ? [] : [id] }
  }
  const withoutExclusive = current.filter((skill) => skill !== "none")
  return {
    ...answers,
    comfortSkills: withoutExclusive.includes(id)
      ? withoutExclusive.filter((skill) => skill !== id)
      : [...withoutExclusive, id]
  }
}

/** Select (or toggle, for multi steps) an option on the current step. Clears the warning. */
export const selectOption = (state: SurveyState, optionId: string): SurveyState => {
  if (state.submitted) return state
  const step = currentStep(state)
  if (step.kind === "text") return state
  const option = step.options.find((candidate) => candidate.id === optionId)
  if (option === undefined) return state
  const answers = step.kind === "multi"
    ? toggleMulti(state.answers, option)
    : setSingle(step, state.answers, option.id)
  // Selecting after flipping away from "Yes" can shorten the step list;
  // clamp the index so the machine never points past the end.
  const maxIndex = activeSteps(answers).length - 1
  return { ...state, answers, warned: false, stepIndex: Math.min(state.stepIndex, maxIndex) }
}

/** Set the free-text answer on the automation-goal step. */
export const setText = (state: SurveyState, text: string): SurveyState => {
  if (state.submitted || currentStep(state).kind !== "text") return state
  return { ...state, answers: { ...state.answers, automationGoal: text }, warned: false }
}

export interface ConfirmResult {
  readonly state: SurveyState
  /** True when the current step validated and the machine advanced (or submitted). */
  readonly advanced: boolean
}

/**
 * Confirm the current step. Required steps with no selection stay put and
 * raise the warning banner; the last valid step marks the survey submitted.
 */
export const confirm = (state: SurveyState): ConfirmResult => {
  if (state.submitted) return { state, advanced: false }
  const step = currentStep(state)
  const valid = !step.required || selectionFor(step, state.answers).length > 0
  if (!valid) return { state: { ...state, warned: true }, advanced: false }
  const steps = activeSteps(state.answers)
  if (state.stepIndex >= steps.length - 1) {
    return { state: { ...state, warned: false, submitted: true }, advanced: true }
  }
  return { state: { ...state, warned: false, stepIndex: state.stepIndex + 1 }, advanced: true }
}

/** Step back one question, keeping answers. No-op on the first step. */
export const back = (state: SurveyState): SurveyState => {
  if (state.submitted || state.stepIndex === 0) return state
  return { ...state, warned: false, stepIndex: state.stepIndex - 1 }
}

/** Map a keyboard key to an option id on the current step (A → first, B → second, …). */
export const optionIdForKey = (state: SurveyState, key: string): string | null => {
  const step = currentStep(state)
  if (step.kind === "text" || step.options.length === 0) return null
  const letter = key.toLowerCase()
  if (letter.length !== 1 || letter < "a" || letter > "z") return null
  const index = letter.charCodeAt(0) - 97
  const option = step.options[index]
  return option === undefined ? null : option.id
}

