import { describe, expect, it } from "vitest"
import {
  activeSteps,
  back,
  confirm,
  currentStep,
  initialSurveyState,
  optionIdForKey,
  progress,
  selectOption,
  selectionFor,
  setText
} from "./surveyMachine.ts"

const answerFirst = (state = initialSurveyState) => selectOption(state, "only-me")

const answerThrough = (goalAnswer: "yes" | "not-yet") => {
  let state = initialSurveyState
  state = selectOption(state, "under-20")
  state = confirm(state).state
  state = selectOption(state, "engineering")
  state = confirm(state).state
  state = selectOption(state, "ai")
  state = confirm(state).state
  state = selectOption(state, goalAnswer)
  return state
}

describe("activeSteps", () => {
  it("hides the automation-goal text step until the user answers Yes", () => {
    expect(activeSteps(initialSurveyState.answers).map((step) => step.id)).toEqual([
      "company-size",
      "role",
      "referral",
      "knows-goal",
      "comfort"
    ])
    const withGoal = { ...initialSurveyState.answers, knowsAutomationGoal: true }
    expect(activeSteps(withGoal).map((step) => step.id)).toContain("automation-goal")
  })
})

describe("single-select steps", () => {
  it("records the selected option into the typed answers", () => {
    const state = answerFirst()
    expect(state.answers.companySize).toBe("only-me")
    expect(selectionFor(currentStep(state), state.answers)).toEqual(["only-me"])
  })

  it("replaces the previous selection rather than accumulating", () => {
    let state = answerFirst()
    state = selectOption(state, "1000-plus")
    expect(state.answers.companySize).toBe("1000-plus")
  })

  it("ignores unknown option ids", () => {
    const state = selectOption(initialSurveyState, "bogus")
    expect(state).toEqual(initialSurveyState)
  })
})

describe("validation", () => {
  it("warns and stays put when OK is pressed with no selection", () => {
    const result = confirm(initialSurveyState)
    expect(result.advanced).toBe(false)
    expect(result.state.warned).toBe(true)
    expect(result.state.stepIndex).toBe(0)
  })

  it("clears the warning when an option is selected", () => {
    const warned = confirm(initialSurveyState).state
    const fixed = selectOption(warned, "only-me")
    expect(fixed.warned).toBe(false)
  })

  it("advances once the required step has a selection", () => {
    const result = confirm(answerFirst())
    expect(result.advanced).toBe(true)
    expect(result.state.stepIndex).toBe(1)
    expect(result.state.warned).toBe(false)
  })

  it("requires the follow-up text to be non-empty", () => {
    let state = confirm(answerThrough("yes")).state
    expect(currentStep(state).id).toBe("automation-goal")
    expect(confirm(state).advanced).toBe(false)
    state = setText(state, "   ")
    expect(confirm(state).advanced).toBe(false)
    state = setText(state, "Triage new issues every morning")
    expect(confirm(state).advanced).toBe(true)
  })
})

describe("conditional follow-up", () => {
  it("inserts the text step only when the user knows their goal", () => {
    expect(currentStep(confirm(answerThrough("yes")).state).id).toBe("automation-goal")
    expect(currentStep(confirm(answerThrough("not-yet")).state).id).toBe("comfort")
  })

  it("discards the typed goal when the answer flips back to Not yet", () => {
    let state = answerThrough("yes")
    state = setText(confirm(state).state, "Automate standup notes")
    expect(state.answers.automationGoal).toBe("Automate standup notes")
    state = back(state)
    state = selectOption(state, "not-yet")
    expect(state.answers.automationGoal).toBe("")
    expect(state.answers.knowsAutomationGoal).toBe(false)
  })
})

describe("multi-select step", () => {
  const atComfort = confirm(answerThrough("not-yet")).state

  it("toggles skills independently", () => {
    let state = selectOption(atComfort, "sql")
    state = selectOption(state, "regex")
    expect(state.answers.comfortSkills).toEqual(["sql", "regex"])
    state = selectOption(state, "sql")
    expect(state.answers.comfortSkills).toEqual(["regex"])
  })

  it("makes None of the above exclusive", () => {
    let state = selectOption(atComfort, "sql")
    state = selectOption(state, "none")
    expect(state.answers.comfortSkills).toEqual(["none"])
    state = selectOption(state, "webhooks")
    expect(state.answers.comfortSkills).toEqual(["webhooks"])
  })

  it("clears back to empty when None is toggled off", () => {
    let state = selectOption(atComfort, "none")
    state = selectOption(state, "none")
    expect(state.answers.comfortSkills).toEqual([])
  })

  it("still validates as required", () => {
    expect(confirm(atComfort).advanced).toBe(false)
  })
})

describe("progress and submission", () => {
  it("counts only active steps", () => {
    expect(progress(initialSurveyState)).toEqual({ current: 0, total: 5 })
    expect(progress(answerThrough("yes"))).toEqual({ current: 3, total: 6 })
  })

  it("submits on the last step and freezes further edits", () => {
    let state = answerThrough("not-yet")
    state = confirm(state).state
    state = selectOption(state, "sql")
    const submitted = confirm(state)
    expect(submitted.advanced).toBe(true)
    expect(submitted.state.submitted).toBe(true)
    expect(selectOption(submitted.state, "regex").answers.comfortSkills).toEqual(["sql"])
  })

  it("walks back without losing answers", () => {
    let state = answerThrough("not-yet")
    state = back(state)
    expect(currentStep(state).id).toBe("referral")
    expect(state.answers.referralSource).toBe("ai")
    expect(back(initialSurveyState).stepIndex).toBe(0)
  })
})

describe("keyboard mapping", () => {
  it("maps letters to options in order", () => {
    expect(optionIdForKey(initialSurveyState, "a")).toBe("only-me")
    expect(optionIdForKey(initialSurveyState, "G")).toBe("not-for-work")
    expect(optionIdForKey(initialSurveyState, "h")).toBeNull()
    expect(optionIdForKey(initialSurveyState, "1")).toBeNull()
  })

  it("returns null on text steps", () => {
    const state = confirm(answerThrough("yes")).state
    expect(optionIdForKey(state, "a")).toBeNull()
  })
})

import type { OnboardingAnswers, OnboardingPersistence } from "./types.ts"

/**
 * Persistence ports for survey answers. The localStorage adapter is real and
 * used today; cloudPersistence is the typed client for the future
 * TODO(cloud-api): POST /api/onboarding/answers endpoint — constructed but
 * not wired into the flow until the cloud round lands.
 */

export const localStoragePersistence = (key = "smithers.onboarding.answers"): OnboardingPersistence => ({
  save: (answers) =>
    Promise.resolve().then(() => {
      window.localStorage.setItem(key, JSON.stringify(answers))
    })
})

export const readLocalAnswers = (key = "smithers.onboarding.answers"): OnboardingAnswers | null => {
  const raw = window.localStorage.getItem(key)
  if (raw === null) return null
  try {
    return JSON.parse(raw) as OnboardingAnswers
  } catch {
    return null
  }
}

/** POST /api/onboarding/answers against the cloud backend. */
export const cloudPersistence = (baseUrl: string): OnboardingPersistence => ({
  save: async (answers) => {
    const response = await fetch(`${baseUrl.replace(/\/$/, "")}/api/onboarding/answers`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(answers)
    })
    if (!response.ok) throw new Error(`onboarding answers POST failed: ${response.status}`)
  }
})

/** Fan out to several ports; local persistence wins ordering and failures surface as one error. */
export const composePersistence = (
  ...ports: ReadonlyArray<OnboardingPersistence>
): OnboardingPersistence => ({
  save: async (answers) => {
    for (const port of ports) await port.save(answers)
  }
})

/* ————————————————————————————————————————————————————————————————
   Onboarding cards. Self-contained: consumes the app's design tokens via
   var() with fallbacks so the harness renders correctly even before the
   app shell loads its stylesheets. Motion is transform/opacity only and
   collapses to instant, fully-readable states under prefers-reduced-motion.
   ———————————————————————————————————————————————————————————————— */

.ob-card {
  --ob-bg: var(--surface, #fffefa);
  --ob-bg-2: var(--surface-2, #efeae0);
  --ob-text: var(--text, #211d18);
  --ob-muted: var(--text-muted, #6e675c);
  --ob-faint: var(--text-faint, #716a5e);
  --ob-border: var(--border, rgb(33 29 24 / 8%));
  --ob-border-strong: var(--border-strong, rgb(33 29 24 / 14%));
  --ob-brand: var(--brand, #0f766e);
  --ob-brand-soft: var(--brand-soft, rgb(15 118 110 / 10%));
  --ob-brand-border: var(--brand-border, rgb(15 118 110 / 28%));
  --ob-gold: var(--confluence, #e8a33d);
  --ob-gold-text: var(--confluence-text, #8c5a08);
  --ob-gold-wash: var(--confluence-wash, rgb(232 163 61 / 16%));
  --ob-warning: var(--warning, #916000);
  --ob-warning-soft: var(--warning-soft, rgb(145 96 0 / 10%));
  --ob-warning-border: var(--warning-border, rgb(145 96 0 / 26%));
  --ob-ring: var(--ring, rgb(15 118 110 / 45%));
  --ob-shadow: var(--shadow-1, 0 1px 3px rgb(33 29 24 / 8%));
  --ob-mono: var(--font-mono, "IBM Plex Mono", ui-monospace, Menlo, monospace);
  --ob-ease: var(--ease-current, cubic-bezier(0.22, 0.61, 0.21, 1));

  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px 20px;
  border: 1px solid var(--ob-border);
  border-radius: var(--r-3, 12px);
  background: var(--ob-bg);
  box-shadow: var(--ob-shadow);
  color: var(--ob-text);
  font-size: var(--fs-md, 0.9375rem);
  line-height: 1.5;
  outline: none;
  overflow: hidden;
  animation: ob-card-in 420ms var(--ob-ease) both;
}

.ob-card:focus-visible {
  box-shadow: var(--ob-shadow), 0 0 0 3px var(--ob-ring);
}

@keyframes ob-card-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ——— Progress bar ——— */

.ob-progress {
  display: flex;
  gap: 4px;
  margin: -4px 0 2px;
}

.ob-progress-segment {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: var(--ob-bg-2);
  overflow: hidden;
}

.ob-progress-segment::after {
  content: "";
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--ob-brand);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 380ms var(--ob-ease);
}

.ob-progress-segment[data-state="done"]::after,
.ob-progress-segment[data-state="current"]::after {
  transform: scaleX(1);
}

.ob-progress-segment[data-state="current"]::after {
  opacity: 0.55;
}

/* ——— Survey question ——— */

.ob-question-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.ob-question-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 6px;
  background: var(--ob-brand-soft);
  border: 1px solid var(--ob-brand-border);
  color: var(--ob-brand);
  font-family: var(--ob-mono);
  font-size: 11px;
  font-weight: 600;
}

.ob-question-title {
  margin: 0;
  font-size: var(--fs-lg, 1.0625rem);
  font-weight: 600;
  letter-spacing: -0.01em;
}

.ob-question-hint {
  margin: -8px 0 0 32px;
  font-size: var(--fs-small, 0.7813rem);
  color: var(--ob-muted);
}

.ob-options {
  display: flex;
  flex-direction: column;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.ob-option {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 12px;
  border: 1px solid var(--ob-border);
  border-radius: var(--r-sm, 8px);
  background: transparent;
  color: var(--ob-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 140ms var(--ob-ease),
    border-color 140ms var(--ob-ease),
    transform 140ms var(--ob-ease);
  animation: ob-row-in 340ms var(--ob-ease) both;
  animation-delay: calc(var(--row, 0) * 45ms);
}

@keyframes ob-row-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.ob-option:hover {
  background: var(--hover-subtle, rgb(33 29 24 / 3%));
  border-color: var(--ob-border-strong);
}

.ob-option:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--ob-ring);
}

.ob-option:active {
  transform: scale(0.995);
}

.ob-option[data-selected="true"] {
  background: var(--ob-brand-soft);
  border-color: var(--ob-brand-border);
}

.ob-option-letter {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 5px;
  border: 1px solid var(--ob-border-strong);
  color: var(--ob-muted);
  font-family: var(--ob-mono);
  font-size: 10.5px;
  text-transform: uppercase;
  transition:
    background-color 140ms var(--ob-ease),
    border-color 140ms var(--ob-ease),
    color 140ms var(--ob-ease);
}

.ob-option[data-selected="true"] .ob-option-letter {
  background: var(--ob-brand);
  border-color: var(--ob-brand);
  color: var(--surface, #fffefa);
}

.ob-option-check {
  flex: none;
  width: 16px;
  height: 16px;
  margin-left: auto;
  border-radius: 4px;
  border: 1px solid var(--ob-border-strong);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: transparent;
  transition:
    background-color 140ms var(--ob-ease),
    border-color 140ms var(--ob-ease),
    color 140ms var(--ob-ease);
}

.ob-option[data-selected="true"] .ob-option-check {
  background: var(--ob-brand);
  border-color: var(--ob-brand);
  color: var(--surface, #fffefa);
}

/* ——— Free text ——— */

.ob-text-input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--ob-border-strong);
  border-radius: var(--r-sm, 8px);
  background: var(--ob-bg);
  color: var(--ob-text);
  font: inherit;
  transition: box-shadow 140ms var(--ob-ease), border-color 140ms var(--ob-ease);
}

.ob-text-input:focus {
  outline: none;
  border-color: var(--ring-border, #3e9e90);
  box-shadow: 0 0 0 3px var(--ob-ring);
}

.ob-text-input::placeholder {
  color: var(--text-placeholder, #716a5e);
}

/* ——— Validation banner ——— */

.ob-warning {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--ob-warning-border);
  border-radius: var(--r-sm, 8px);
  background: var(--ob-warning-soft);
  color: var(--ob-warning);
  font-size: var(--fs-small, 0.7813rem);
  animation: ob-warn-in 300ms var(--ob-ease) both;
}

@keyframes ob-warn-in {
  0% {
    opacity: 0;
    transform: translateX(0);
  }
  30% {
    opacity: 1;
    transform: translateX(-4px);
  }
  55% {
    transform: translateX(3px);
  }
  75% {
    transform: translateX(-2px);
  }
  100% {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ——— Actions ——— */

.ob-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ob-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: var(--ctl-h, 32px);
  padding: 0 14px;
  border-radius: var(--r-sm, 8px);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition:
    background-color 140ms var(--ob-ease),
    transform 140ms var(--ob-ease),
    opacity 140ms var(--ob-ease);
}

.ob-btn:active {
  transform: scale(0.97);
}

.ob-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--ob-ring);
}

.ob-btn-primary {
  background: var(--inverse-bg, #211d18);
  color: var(--inverse-text, #f7f4ee);
}

.ob-btn-primary:hover {
  background: var(--inverse-bg-hover, #37312a);
}

.ob-btn-ghost {
  background: transparent;
  border-color: var(--ob-border-strong);
  color: var(--ob-muted);
}

.ob-btn-ghost:hover {
  color: var(--ob-text);
  background: var(--hover-subtle, rgb(33 29 24 / 3%));
}

.ob-key-hint {
  margin-left: auto;
  font-family: var(--ob-mono);
  font-size: 11px;
  color: var(--ob-faint);
}

.ob-key-hint kbd {
  padding: 1px 5px;
  border: 1px solid var(--ob-border-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  font-family: inherit;
}

/* ——— Concept walkthrough cards ——— */

.ob-concept-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.ob-concept-kicker {
  font-family: var(--ob-mono);
  font-size: var(--fs-kicker, 0.6875rem);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ob-brand);
}

.ob-concept-title {
  margin: 0;
  font-size: var(--fs-lg, 1.0625rem);
  font-weight: 600;
  letter-spacing: -0.01em;
}

.ob-concept-def {
  margin: 0;
  color: var(--ob-muted);
}

.ob-demo {
  position: relative;
  border: 1px solid var(--ob-border);
  border-radius: var(--r-sm, 8px);
  background: var(--ob-bg-2);
  overflow: hidden;
  min-height: 148px;
