.ob-connector-desc {
  color: var(--ob-muted);
  font-size: var(--fs-small, 0.7813rem);
  line-height: 1.4;
}

.ob-connector-check {
  flex: none;
  margin-left: auto;
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1px solid var(--ob-border-strong);
  display: inline-flex;
  align-items: center;
  justify-content: center;
