.ob-connector[data-selected="true"] .ob-connector-check {
  background: var(--ob-brand);
  border-color: var(--ob-brand);
  color: var(--surface, #fffefa);
}

.ob-picker-status {
  color: var(--ob-muted);
  font-size: var(--fs-small, 0.7813rem);
  padding: 8px 2px;
}

/* ——— Reduced motion: every animation collapses; all content stays visible ——— */

@media (prefers-reduced-motion: reduce) {
  .ob-card,
  .ob-option,
  .ob-warning,
  .ob-roster-row,
  .ob-connector {
    animation: none;
  }

  .ob-progress-segment::after,
  .ob-option,
  .ob-btn,
  .ob-connector,
  .ob-option-letter,
  .ob-option-check,
  .ob-connector-check,
  .ob-text-input {
    transition: none;
  }

  .ob-tree-row,
  .ob-doc-typed,
  .ob-flows-typed {
    animation: none;
    opacity: 1;
    transform: none;
    max-width: 100%;
  }

  .ob-cursor {
    animation: none;
    opacity: 1;
    transform: translateX(var(--x, 120px));
  }

  .ob-flow-chip,
  .ob-flow-chip::before {
    animation: none;
    opacity: 1;
    transform: none;
    border-color: var(--ob-brand-border);
    color: var(--ob-brand);
  }

  .ob-flow-chip::before {
    background: var(--ob-brand);
  }

  .ob-conn-pulse {
    animation: none;
    opacity: 1;
  }

  .ob-flows-caret {
    animation: none;
  }
}

import { useEffect, useRef } from "react"
import type { KeyboardEvent } from "react"
import type { SurveyStep } from "./content.ts"
import * as Machine from "./surveyMachine.ts"
import type { SurveyState } from "./surveyMachine.ts"

const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

export interface SurveyCardProps {
  readonly state: SurveyState
  readonly step: SurveyStep
  readonly onSelect: (optionId: string) => void
  readonly onText: (text: string) => void
  readonly onConfirm: () => void
  readonly onBack: () => void
}

/**
 * One n8n/Typeform-style survey question: numbered chip, lettered option
 * rows, segmented progress bar, OK button with a required-validation amber
 * banner. Keyboard-first — letters select, Enter confirms, Backspace goes
 * back. Renders nothing once the machine has submitted.
 */
export const SurveyCard = ({ state, step, onSelect, onText, onConfirm, onBack }: SurveyCardProps) => {
  const root = useRef<HTMLDivElement | null>(null)
  const { current, total } = Machine.progress(state)
  const selection = Machine.selectionFor(step, state.answers)

  useEffect(() => {
    root.current?.focus({ preventScroll: true })
  }, [step.id])

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" && step.kind !== "text") {
      event.preventDefault()
      onConfirm()
      return
    }
    if (event.key === "Backspace" && step.kind !== "text") {
      event.preventDefault()
      onBack()
      return
    }
    if (step.kind !== "text" && !event.metaKey && !event.ctrlKey && !event.altKey) {
      const optionId = Machine.optionIdForKey(state, event.key)
      if (optionId !== null) {
        event.preventDefault()
        onSelect(optionId)
      }
    }
  }

  return (
    <div
      ref={root}
      className="ob-card"
      data-testid="ob-survey-card"
      tabIndex={-1}
      role="group"
      aria-label={`Question ${current + 1} of ${total}: ${step.title}`}
      onKeyDown={onKeyDown}
    >
      <div className="ob-progress" aria-hidden="true">
        {Array.from({ length: total }, (_, index) => (
          <span
            key={index}
            className="ob-progress-segment"
            data-state={index < current ? "done" : index === current ? "current" : "todo"}
          />
        ))}
      </div>

      <div className="ob-question-head">
        <span className="ob-question-chip">{current + 1}</span>
        <h3 className="ob-question-title">{step.title}</h3>
      </div>
      {step.hint !== null && <p className="ob-question-hint">{step.hint}</p>}

      {step.kind === "text"
        ? (
          <input
            className="ob-text-input"
            data-testid="ob-survey-text"
            type="text"
            value={state.answers.automationGoal}
            placeholder={step.placeholder ?? ""}
            aria-label={step.title}
            onChange={(event) => onText(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault()
                onConfirm()
              }
              event.stopPropagation()
            }}
          />
        )
        : (
          <ul className="ob-options">
            {step.options.map((option, index) => {
              const selected = selection.includes(option.id)
              return (
                <li key={option.id} style={{ "--row": index } as React.CSSProperties}>
                  <button
                    type="button"
                    className="ob-option"
                    data-selected={selected}
                    data-testid={`ob-option-${option.id}`}
                    aria-pressed={selected}
                    onClick={() => onSelect(option.id)}
                  >
                    <span className="ob-option-letter">{LETTERS[index]}</span>
                    <span>{option.label}</span>
                    {step.kind === "multi" && (
                      <span className="ob-option-check" aria-hidden="true">✓</span>
                    )}
                  </button>
                </li>
              )
            })}
          </ul>
        )}

      {state.warned && (
        <div className="ob-warning" role="alert" data-testid="ob-survey-warning">
          {step.kind === "text" ? "A quick sentence first — this one's required." : "Pick an option to continue — this one's required."}
        </div>
      )}

      <div className="ob-actions">
        <button type="button" className="ob-btn ob-btn-primary" data-testid="ob-survey-ok" onClick={onConfirm}>
          {step.confirmLabel}
        </button>
        {current > 0 && (
          <button type="button" className="ob-btn ob-ghost" onClick={onBack}>
            Back
          </button>
        )}
        {step.kind !== "text" && (
          <span className="ob-key-hint">
            press <kbd>{LETTERS[0]}</kbd>–<kbd>{LETTERS[step.options.length - 1]}</kbd> to choose,{" "}
            <kbd>Enter ↵</kbd>
          </span>
        )}
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from "react"
import * as Machine from "./surveyMachine.ts"
import type { SurveyState } from "./surveyMachine.ts"
import { SurveyCard } from "./SurveyCard.tsx"
import type { OnboardingAnswers, OnboardingPersistence } from "./types.ts"

export interface OnboardingSurveyProps {
  readonly persistence: OnboardingPersistence
  readonly onComplete?: (answers: OnboardingAnswers) => void
}

/**
 * The full five-question survey as one chat card. Drives the pure machine,
 * persists the typed OnboardingAnswers through the injected port on submit,
 * then shows a compact done state. Wiring the answers into the agent's
 * context happens in a later round — the card only collects and reports.
 */
export const OnboardingSurvey = ({ persistence, onComplete }: OnboardingSurveyProps) => {
  const [state, setState] = useState<SurveyState>(Machine.initialSurveyState)
  const [saveError, setSaveError] = useState<string | null>(null)
  const saved = useRef(false)

  useEffect(() => {
    if (!state.submitted || saved.current) return
    saved.current = true
    let cancelled = false
    persistence
      .save(state.answers)
      .then(() => {
        if (!cancelled) onComplete?.(state.answers)
      })
      .catch((error: unknown) => {
        if (!cancelled) setSaveError(error instanceof Error ? error.message : "Could not save your answers")
      })
    return () => {
      cancelled = true
    }
  }, [state.submitted, state.answers, persistence, onComplete])

  if (state.submitted) {
    return (
      <div className="ob-card" data-testid="ob-survey-done">
        <div className="ob-question-head">
          <span className="ob-question-chip">✓</span>
          <h3 className="ob-question-title">Thanks — that's all I need.</h3>
        </div>
        {saveError === null
          ? <p className="ob-concept-def">Your answers are saved. On to the tour.</p>
          : <p className="ob-warning" role="alert">Saved locally, but the cloud copy failed: {saveError}</p>}
      </div>
    )
  }

  const step = Machine.currentStep(state)
  return (
    <SurveyCard
      state={state}
      step={step}
      onSelect={(optionId) => setState((current) => Machine.selectOption(current, optionId))}
      onText={(text) => setState((current) => Machine.setText(current, text))}
      onConfirm={() => setState((current) => Machine.confirm(current).state)}
      onBack={() => setState((current) => Machine.back(current))}
    />
  )
}

