    {services.map((service) => (
      <g key={service.id}>
        <rect className="ob-conn-node" x="16" y={service.y - 14} width="48" height="28" rx="8" />
        <text className="ob-conn-label" x="40" y={service.y + 4}>{service.label}</text>
      </g>
    ))}
    <g>
      <rect className="ob-conn-repo" x={repoX - 26} y={repoY - 18} width="64" height="36" rx="8" />
      <text className="ob-conn-label" x={repoX + 6} y={repoY + 4}>repo</text>
    </g>
  </svg>
)

input.newString:
.ob-conn-pulse {
  fill: var(--ob-brand);
  opacity: 0;
  offset-rotate: 0deg;
  animation: ob-pulse-travel 3.2s linear infinite;
  animation-delay: var(--d, 0ms);
}

@keyframes ob-pulse-travel {
  0% {
    opacity: 0;
    offset-distance: 0%;
  }
  8% {
    opacity: 1;
  }
  70% {
    opacity: 1;
    offset-distance: 100%;
  }
  86%, 100% {
    opacity: 0;
    offset-distance: 100%;
  }
}

input.oldString:
.ob-conn-pulse {
  fill: var(--ob-brand);
  opacity: 0;
  animation: ob-pulse-fade 3.2s linear infinite;
  animation-delay: var(--d, 0ms);
}

@keyframes ob-pulse-fade {
  0% {
    opacity: 0;
  }
  8%, 70% {
    opacity: 1;
  }
  86%, 100% {
    opacity: 0;
  }
}
